// Task_Trigger_Config Kind-specific parameters. The relevant subset depends on `type`: `manual` → empty; `once` → `at_ms`; `every` → `every_ms`; `recurring` → exactly one of `cron_expr` (legacy) or `rrule` (+ required `dtstart_ms` and `tz`). Validated server-side against `type`. This object is the open growth surface — v0.3 event kinds add their own keys here without changing the outer shape.
type Task_Trigger_Config struct {
	// AtMs Unix epoch milliseconds for a one-shot fire. Required when `type = once`; ignored otherwise.
	AtMs *int64 `json:"at_ms,omitempty"`

	// CronExpr Cron expression (5 or 6 fields), legacy path. Valid only when `type = recurring`; ignored otherwise. Exactly one of `cron_expr` / `rrule` is present on a `recurring` trigger — never both.
	CronExpr *string `json:"cron_expr,omitempty"`

	// DtstartMs Anchor instant for `rrule` — the first occurrence's wall-clock moment, Unix epoch milliseconds. Required sibling of `rrule`; ignored otherwise.
	DtstartMs *int64 `json:"dtstart_ms,omitempty"`

	// EveryMs Interval in milliseconds between fires. Required when `type = every` (minimum 1000ms); ignored otherwise.
	EveryMs *int64 `json:"every_ms,omitempty"`

	// Rrule RFC 5545 RRULE body (no `RRULE:` prefix), e.g. `FREQ=WEEKLY;INTERVAL=2;BYDAY=MO;COUNT=10`. Valid only when `type = recurring`; ignored otherwise. Exactly one of `cron_expr` / `rrule` is present on a `recurring` trigger — never both. Requires the sibling keys `dtstart_ms` and `tz`. Server-validated: input bounds (≤512 chars, no `FREQ=SECONDLY`, no foreign `BYSECOND`), bounded-window minimum-gap scan (≥60s between occurrences), liveness (must produce an occurrence within 5 years of `dtstart_ms`), and `COUNT` ≤ 100000.
	Rrule *string `json:"rrule,omitempty"`

	// Tz IANA timezone name in which `rrule`'s wall-clock times are interpreted (e.g. "Europe/Berlin"). Required sibling of `rrule`; ignored otherwise. Occurrences are wall-clock in this zone across DST transitions (Timezone Semantics).
	Tz                   *string                `json:"tz,omitempty"`
	AdditionalProperties map[string]interface{} `json:"-"`
}

// TaskTriggerType The trigger kind (discriminator). Tier 2 ships time-only kinds; v0.3 adds event kinds (`on_task`/`on_agent`/`on_message`/`webhook`/`on_condition`) additively.
type TaskTriggerType string

// TaskCreateRequest Request body for POST /tasks — the ONE unified create form (Detail #8) that replaces the two legacy create bodies (`TaskCreateRequest` and `BoardTaskCreateRequest`). No back-compat aliases.
// Landing rule (Detail #8): every created task lands in `inbox`. Nothing auto-lands in `next`; only a fully-captured task can be manually triaged to `next` via PATCH. `status` is therefore NOT a create-time field — the server always seeds `inbox`.
// Start semantics (Detail #8): a task with no trigger (`manual`) starts when dragged to `in_progress` / Run; a task with a time trigger fires itself. The "Create & Run now" UX (create + start immediately) is a client action layered on top of this create + a subsequent start, not a distinct request field.
type TaskCreateRequest struct {
	// Action Task action type. Tier 2 accepts `llm` only; the enum grows additively in v0.3.
	Action TaskCreateRequestAction `json:"action"`

	// AgentId Optional agent to assign the task to.
	AgentId *string `json:"agent_id,omitempty"`

	// BlockedBy Task IDs this task depends on (depends-on / blocked_by). Each must exist and must not create a cycle (validated at creation).
	BlockedBy *[]string `json:"blocked_by,omitempty"`

	// Criteria Optional initial acceptance criteria (Definition of Done, ADR-049 D2/D5/FR-3). Agent tool paths reject a create with zero criteria; human/UI creation may leave this empty (soft tier).
	Criteria *[]struct {
		// Author Recorded identity of whoever authored this criterion (ADR D2 rule 3; mandatory — 400 if absent). A cross-agent-authored machine check (author identity != assignee agent id) requires assignee-owner confirmation unless waived by a workspace setting.
		Author struct {
			// Id Agent ID or username of the author.
			Id string `json:"id"`

			// Kind Whether this criterion was authored by an agent or a human user.
			Kind TaskCreateRequestCriteriaAuthorKind `json:"kind"`
		} `json:"author"`

		// Behavior Present iff `kind == behavior` (400 if present with a different `kind` — no mixed shape); required iff `kind == behavior` (400 if absent). ADR-052 FR-034 — resolved deterministically from the session's per-entry tool-call log (no LLM verifier dispatch). Unknown fields are rejected 400 (`additionalProperties: false`). `min_count >= 0`, and `min_count == 0` with `max_count == 0` expresses "never call this tool"; when both are present, `max_count >= min_count` (400 if violated).
		Behavior *struct {
			// MaxCount Maximum number of successful calls of `tool` allowed within `scope`. Absent = no upper bound. Must be >= `min_count` when present.
			MaxCount *int `json:"max_count,omitempty"`

			// MinCount Minimum number of successful calls of `tool` required within `scope`.
			MinCount *int `json:"min_count,omitempty"`

			// Scope Window the tool-call count is evaluated over. `attempt` = the current retry attempt only. `task_session` (default) = the whole session backing the task/plan-member run.
			Scope *TaskCreateRequestCriteriaBehaviorScope `json:"scope,omitempty"`

			// Tool Name of the tool whose successful-call count is checked.
			Tool string `json:"tool"`
		} `json:"behavior,omitempty"`

		// Check Present iff `kind == check` (400 if present with `kind == prose` — no mixed shape); required iff `kind == check` (400 if absent). Dispatched through the assignee agent's existing `bash` tool machinery (ADR D2 rule 1) — same tool registry, policy resolution, sandbox enforcement, and audit trail as any other `bash` call. Policy `allow` runs; `ask` resolves to deny (no interactive approver mid-loop); `deny` fails the criterion closed.
		Check *struct {
			// Command Shell command run through the assignee's `bash` tool.
			Command string `json:"command"`

			// ExpectedExitCode Exit code that counts as PASS (`met`) for this check.
			ExpectedExitCode int `json:"expected_exit_code"`
		} `json:"check,omitempty"`

		// Id Server-set criterion identifier (UUID). Absent on a create-time payload; always present once persisted.
		Id *string `json:"id,omitempty"`

		// Kind `check` = machine-checkable command with an expected exit code, run via the assignee's `bash` tool. `prose` = free-text statement judged by the Judge System Agent. `behavior` (ADR-052 FR-034) = a deterministic machine check over the session's own tool-call log — the comparator is the count of successful calls of a named tool within a scope, resolved WITHOUT the LLM verifier or `inspect_session`. Ladder order: machine-check (`check`) -> `behavior` -> subjective (`prose`, verifier).
		Kind TaskCreateRequestCriteriaKind `json:"kind"`

		// Status Per-run judgement status. `pending` before any judge round; `met` / `unmet` set by the most recent `JudgeVerdict.per_criterion` entry. Absence of evidence/a verdict never defaults to `met` (NFR-2).
		Status TaskCreateRequestCriteriaStatus `json:"status"`

		// Text The criterion statement (`kind: prose`) or a human-readable description of what the check verifies (`kind: check`).
		Text string `json:"text"`
	} `json:"criteria,omitempty"`

	// Description Optional free-form description.
	Description *string `json:"description,omitempty"`

	// Due Optional deadline (RFC 3339 UTC).
	Due *time.Time `json:"due,omitempty"`

	// IsJoin ADR-053 §Contract Surface — true marks this member as an authored join/assemble member with its own criteria. Absent/false is the common case — no schema `default:` (see `Task.yaml`'s `is_join` for why: combining `default:` with an absent-from-`required` field makes openapi-typescript emit it as non-optional regardless).
	IsJoin *bool `json:"is_join,omitempty"`

	// MaxAttempts Per-task override of the attempt ceiling before the goal loop wakes the owner (ADR-049 D7/FR-9). Null/absent inherits the global `PlanningConfig.task_max_attempts` default (3).
	MaxAttempts *int `json:"max_attempts,omitempty"`

	// ParentTaskId Optional parent task ID — set when creating a subtask (delegation / decomposition child).
	ParentTaskId *string `json:"parent_task_id,omitempty"`

	// PlanId Optional Plan to group this task under (ADR-049 D1/D4). Same-workspace FK — rejected 400 if the plan is in a different workspace.
	PlanId *string `json:"plan_id,omitempty"`

	// Priority Task priority from 1 (highest) to 5 (lowest). Defaults to 3.
	Priority *int `json:"priority,omitempty"`

	// Prompt Optional agent prompt for an `llm` action.
	Prompt *string `json:"prompt,omitempty"`

	// SourceChannel Originating channel for a delegated task (Detail
	SourceChannel *string `json:"source_channel,omitempty"`

	// SourceChatId Originating chat/conversation ID for a delegated task (Detail
	SourceChatId *string `json:"source_chat_id,omitempty"`

	// Stream ADR-053 §Contract Surface — the parallel-group id this member belongs to.
	Stream *string `json:"stream,omitempty"`

	// Surface UI surface ownership (Detail #5). Defaults to `user`. Dedicated-UI features (e.g. heartbeat) set their own surface so the task is hidden from general views.
	Surface *TaskCreateRequestSurface `json:"surface,omitempty"`

	// Tags Workspace-scoped, free-form tags (ADR-049 D1) — lowercase, trimmed, deduplicated after normalization, at most 16 per task, each at most 64 characters.
	Tags *[]string `json:"tags,omitempty"`

	// Title Task title.
	Title string `json:"title"`

	// Todos Optional initial checklist items.
	Todos *[]struct {
		// Status Tri-state checklist item status. `pending` = not started, `in_progress` = currently being worked, `completed` = done.
		Status TaskCreateRequestTodosStatus `json:"status"`

		// Text The checklist item text.
		Text string `json:"text"`
	} `json:"todos,omitempty"`

	// Trigger When (and how) a Task fires (Detail #3). Modelled as an extensible `{type, config}` shape so the v0.3 multi-trigger / boolean-composition future can grow ADDITIVELY, but RESTRICTED to time-only kinds in Tier 2.
	// ## Tier 2 (now) `type` is one of:
	//   - `manual`    — no automatic trigger. The task starts when a human drags its
	//                   card into `in_progress`, or via Run / Create & Run. For an
	//                   `llm` action that runs the assigned agent. `config` is empty.
	//   - `once`      — fire exactly once at an absolute instant. `config.at_ms` is the
	//                   Unix epoch-milliseconds instant (required).
	//   - `every`     — fire repeatedly on a fixed interval. `config.every_ms` is the
	//                   interval in milliseconds (required, min 1000). Each fire spawns
	//                   a FRESH run (fresh session + run history + pause).
	//   - `recurring` — fire on a repeat rule. `config` carries EXACTLY ONE of:
	//                   `cron_expr` (legacy, 5/6-field cron expression, still accepted
	//                   and validated via gronx) or `rrule` (RFC 5545 RRULE body, e.g.
	//                   `FREQ=WEEKLY;INTERVAL=2;BYDAY=MO;COUNT=10`) plus its required
	//                   siblings `dtstart_ms` (anchor instant) and `tz` (IANA zone).
	//                   Each fire spawns a FRESH run.
	//
	// `once`/`every`/`recurring` triggers are executed by the existing per-agent Schedules engine (`pkg/cron`) acting as the trigger executor — a schedule is just a task with a time trigger; a heartbeat is a `recurring` task with `surface: heartbeat` (Main-only). This folds in the legacy `ScheduleTrigger` semantics (`at_ms` / `every_ms` / `cron_expr`); the Task's own trigger is this type rather than `ScheduleTrigger`.
	// ## v0.3 growth path (design intent — DO NOT build in Tier 2) The discriminated `type` enum grows additively with event kinds: `on_task` (another task reaches a status), `on_agent` (idle/error — idle is the autonomous-loop primitive), `on_message` (channel match), `webhook`, and `on_condition` (threshold). Each new kind carries its own keys inside `config` (e.g. `on_task` → `{task_id, status}`; `on_message` → `{channel, pattern}`; `webhook` → `{secret_ref}`). Boolean composition (AND/OR trigger expressions, not a flat list) will be introduced as an additional optional `expr` field or a `composite` type wrapping child TaskTriggers — additive, leaving the Tier 2 `{type, config}` shape intact. Because every field beyond `type` lives under the open `config` object, none of these additions break the Tier 2 wire shape.
	Trigger *struct {
		// Config Kind-specific parameters. The relevant subset depends on `type`: `manual` → empty; `once` → `at_ms`; `every` → `every_ms`; `recurring` → exactly one of `cron_expr` (legacy) or `rrule` (+ required `dtstart_ms` and `tz`). Validated server-side against `type`. This object is the open growth surface — v0.3 event kinds add their own keys here without changing the outer shape.
		Config TaskCreateRequest_Trigger_Config `json:"config"`

		// Type The trigger kind (discriminator). Tier 2 ships time-only kinds; v0.3 adds event kinds (`on_task`/`on_agent`/`on_message`/`webhook`/`on_condition`) additively.
		Type TaskCreateRequestTriggerType `json:"type"`
	} `json:"trigger,omitempty"`

	// WorkspaceId Workspace this task belongs to. Required — every task is workspace-scoped.
	WorkspaceId string `json:"workspace_id"`

	// WriteSet ADR-053 §Contract Surface. Concrete paths this plan member creates/ edits — see `Task.write_set`. Meaningful only alongside `plan_id`; empty/absent for an exploratory member (D10) or a standalone task.
	WriteSet *[]string `json:"write_set,omitempty"`
}

