type TodoStatus string

// TokenBudgetStatus App-level OVERALL token budget status for the Usage screen (ADR-053 §Contract Surface, D12/R§8.3, FE-6). ONE shared pool across the whole install — no per-plan budgets, no money caps, no `IsPrivilegedAgent` exemption (D12 deliberately removes the core-agent exemption). Debited by owner + member + verifier + Judge turns from provider-reported usage via a single atomic `debitTokenBudget(n)` critical section (INV-8).
type TokenBudgetStatus struct {
	// Advisory Present (non-empty) only when `budget == 0` — the persistent "unbounded — set a budget" Usage-screen advisory (R§8.3a). Also used for the one-time token≠dollar-cap warning surfaced when an operator first sets a budget (R§8.3b).
	Advisory *string `json:"advisory,omitempty"`

	// Budget The operator-set overall token budget. `0` is the unbounded sentinel (R§8.3a — default on a fresh install) — the Usage screen shows `advisory` persistently while this is 0.
	Budget int `json:"budget"`

	// ByScope Per-scope spend accounting (owner/member/verifier/Judge turns each debit the SAME shared pool — this breakdown is display-only, not a separate budget per scope).
	ByScope struct {
		// Judge Tokens consumed by the Judge's own adjudication calls.
		Judge int `json:"judge"`

		// Member Tokens consumed by plan-member / delegated-child turns.
		Member int `json:"member"`

		// Owner Tokens consumed by plan-owner / goal-owner turns.
		Owner int `json:"owner"`

		// Verifier Tokens consumed by verifier/Judge-adjacent worker turns.
		Verifier int `json:"verifier"`
	} `json:"by_scope"`

	// Consumed Total tokens debited so far this budget period, reconciled from the persisted counter at boot. May overshoot `budget` by up to the sum of in-flight turn costs at the moment of exhaustion (INV-8 — post-turn provider-reported debit, graceful wind-down, never a mid-tool hard cut).
	Consumed int `json:"consumed"`

	// Exhausted True once the pool has crossed zero. Every running scope brakes to `failed(budget_exhausted)` at its next turn/adjudication boundary (INV-8) — never mid-tool.
	Exhausted bool `json:"exhausted"`

	// Remaining `budget - consumed`, floored at 0. Meaningless (ignore) when `budget == 0` (unbounded).
	Remaining int `json:"remaining"`
}

// TokenUsageSummary Per-agent token usage summary for a given time period. Aggregated from SessionMeta.Stats across all session files. subagent_3p (external CLI workers) are excluded — they run on a separate engine and their tokens are not tracked.
type TokenUsageSummary struct {
	Agents []struct {
		AgentId   string `json:"agent_id"`
		AgentName string `json:"agent_name"`

		// ByModel Per-model breakdown for this agent. Absent when no model data is available.
		ByModel *map[string]struct {
			// CacheRead Cache-read tokens (served from KV cache) for this model. Additive to total alongside in and out, matching the provider's own usage accounting (total = in + out + cache_read + cache_write) — NOT a subset of total.
			CacheRead *int `json:"cache_read,omitempty"`

			// CacheWrite Cache-write tokens (written into a new cache entry) for this model. Additive to total alongside in and out — see cache_read's description.
			CacheWrite *int `json:"cache_write,omitempty"`

			// In Uncached input (prompt) tokens for this model, as reported by the provider. Populated on the assistant-turn write path. Entries written before the provider split was recorded carry 0 here with the whole turn total in total, so a 0 means "not recorded", not "no input tokens".
			In *int `json:"in,omitempty"`

			// Out Output (completion) tokens for this model, as reported by the provider. Populated on the assistant-turn write path. Entries written before the provider split was recorded carry 0 here with the whole turn total in total, so a 0 means "not recorded", not "no output tokens".
			Out *int `json:"out,omitempty"`

			// Total Authoritative total tokens recorded for this model, as reported by the provider. Additive: total = in + out + cache_read + cache_write once the provider's input/output split has been recorded on an entry (a non-zero in and/or out). Entries predating that split carry 0 in both in and out while total still reflects the full turn (out was not yet split from cache/completion), so always read total directly rather than reconstructing it from the other fields.
			Total int `json:"total"`
		} `json:"by_model,omitempty"`

		// TokensCacheRead Total cache-read tokens for this agent in the period.
		TokensCacheRead *int `json:"tokens_cache_read,omitempty"`

		// TokensCacheWrite Total cache-write tokens for this agent in the period.
		TokensCacheWrite *int `json:"tokens_cache_write,omitempty"`
		TokensIn         int  `json:"tokens_in"`
		TokensOut        int  `json:"tokens_out"`
		TokensTotal      int  `json:"tokens_total"`
	} `json:"agents"`

	// ByModel Cross-agent per-model breakdown for the period. Keys are model name strings. Absent when no model data is available.
	ByModel *map[string]struct {
		// CacheRead Cache-read tokens (served from KV cache) for this model. Additive to total alongside in and out, matching the provider's own usage accounting (total = in + out + cache_read + cache_write) — NOT a subset of total.
		CacheRead *int `json:"cache_read,omitempty"`

		// CacheWrite Cache-write tokens (written into a new cache entry) for this model. Additive to total alongside in and out — see cache_read's description.
		CacheWrite *int `json:"cache_write,omitempty"`

		// In Uncached input (prompt) tokens for this model, as reported by the provider. Populated on the assistant-turn write path. Entries written before the provider split was recorded carry 0 here with the whole turn total in total, so a 0 means "not recorded", not "no input tokens".
		In *int `json:"in,omitempty"`

		// Out Output (completion) tokens for this model, as reported by the provider. Populated on the assistant-turn write path. Entries written before the provider split was recorded carry 0 here with the whole turn total in total, so a 0 means "not recorded", not "no output tokens".
		Out *int `json:"out,omitempty"`

		// Total Authoritative total tokens recorded for this model, as reported by the provider. Additive: total = in + out + cache_read + cache_write once the provider's input/output split has been recorded on an entry (a non-zero in and/or out). Entries predating that split carry 0 in both in and out while total still reflects the full turn (out was not yet split from cache/completion), so always read total directly rather than reconstructing it from the other fields.
		Total int `json:"total"`
	} `json:"by_model,omitempty"`

	// Partial True when one or more session stores failed to load during aggregation, so the totals may under-count. Clients should surface a "some sessions could not be read" indicator rather than presenting the number as authoritative. Absent (or false) when every store loaded cleanly.
	Partial *bool `json:"partial,omitempty"`

	// PartialErrorCount Number of session-store load errors encountered (present only when partial is true).
	PartialErrorCount *int `json:"partial_error_count,omitempty"`

	// PeriodEnd End of the aggregation period (exclusive), UTC.
	PeriodEnd time.Time `json:"period_end"`

	// PeriodStart Start of the aggregation period (inclusive), UTC.
	PeriodStart time.Time `json:"period_start"`

	// TokensCacheRead Grand total cache-read tokens across all agents in the period.
	TokensCacheRead *int `json:"tokens_cache_read,omitempty"`

	// TokensCacheWrite Grand total cache-write tokens across all agents in the period.
	TokensCacheWrite *int `json:"tokens_cache_write,omitempty"`
}

// ToolApprovalActionRequest Request body for POST /api/v1/tool-approvals/{approval_id}. Resolves a pending tool call approval by approving, denying, cancelling, or approving-and-remembering ("always") it.
type ToolApprovalActionRequest struct {
	// Action Action to take on this approval. approve — allow this single invocation. deny    — reject this single invocation. cancel  — cancel this invocation (e.g. modal dismissed / turn aborted). always  — allow this invocation AND record a session-scoped "Always Allow" grant for (session, agent, tool) so future matching calls in the same session auto-approve without re-prompting.
	Action ToolApprovalActionRequestAction `json:"action"`
}

// ToolApprovalActionRequestAction Action to take on this approval. approve — allow this single invocation. deny    — reject this single invocation. cancel  — cancel this invocation (e.g. modal dismissed / turn aborted). always  — allow this invocation AND record a session-scoped "Always Allow" grant for (session, agent, tool) so future matching calls in the same session auto-approve without re-prompting.
type ToolApprovalActionRequestAction string

// ToolApprovalResponse Response from POST /api/v1/tool-approvals/{approval_id}. Confirms that the approval action was processed.
type ToolApprovalResponse struct {
	// Action The action that was applied. Echoes the request action, including "always" (approve-and-remember).
	Action ToolApprovalResponseAction `json:"action"`

	// ApprovalId The approval ID that was resolved.
	ApprovalId string `json:"approval_id"`

	// GrantRecorded Present only when action is "always". True when the standing Always Allow grant was stored. False means this call was approved once, but the next identical call will ask again — the grant did not stick (missing session, agent, or tool identity on the approval).
	GrantRecorded *bool `json:"grant_recorded,omitempty"`

	// Status Result status. Always "ok" when the action was accepted.
	Status ToolApprovalResponseStatus `json:"status"`
}

// ToolApprovalResponseAction The action that was applied. Echoes the request action, including "always" (approve-and-remember).
